#!/usr/bin/env node
/**
 * Initial Load Script for Orders Data
 *
 * Loads historical orders data from S3-style file system into ClickHouse
 * Handles mixed formats (CSV, CSV.GZ, JSONL, Parquet) and missing columns
 */

import * as fs from 'fs';
import * as path from 'path';
import { execSync } from 'child_process';

// Configuration from environment variables
const config = {
  S3_ENDPOINT: process.env.S3_ENDPOINT || 'file:///data/s3',
  S3_BUCKET: process.env.S3_BUCKET || 'foo-bar-prod-exports',
  S3_PREFIX: process.env.S3_PREFIX || 'initial-load/orders/2026-01/',
  S3_MANIFEST_PATH: process.env.S3_MANIFEST_PATH || '/data/s3/foo-bar-prod-exports/initial-load/orders/2026-01/manifest.csv',
};

// Base path for data files
const BASE_PATH = '/data/s3';

interface ManifestEntry {
  object_key: string;
  format: string;
  should_load: boolean;
  row_count: number;
}

/**
 * Parse CSV manifest file
 */
function parseManifest(manifestPath: string): ManifestEntry[] {
  const content = fs.readFileSync(manifestPath, 'utf-8');
  const lines = content.trim().split('\n');
  const header = lines[0].split(',');

  const entries: ManifestEntry[] = [];
  for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(',');
    if (values.length >= 4) {
      entries.push({
        object_key: values[0],
        format: values[1],
        should_load: values[2] === 'true',
        row_count: parseInt(values[3], 10)
      });
    }
  }

  return entries;
}

/**
 * Execute ClickHouse query via moose CLI
 */
function executeQuery(query: string): string {
  try {
    console.log(`Executing query: ${query.substring(0, 100)}...`);
    const result = execSync(`moose query "${query.replace(/"/g, '\\"')}"`, { encoding: 'utf-8' });
    return result;
  } catch (error: any) {
    console.error(`Query failed: ${error.message}`);
    throw error;
  }
}

/**
 * Load a CSV file (with or without promo_code column)
 */
function loadCsvFile(filePath: string, objectKey: string): void {
  console.log(`Loading CSV file: ${filePath}`);

  // First, check the header to see if promo_code column exists
  const firstLine = execSync(`head -n 1 "${filePath}"`, { encoding: 'utf-8' }).trim();
  const hasPromoCode = firstLine.includes('promo_code');

  if (hasPromoCode) {
    // Standard CSV with all columns
    const query = `
      INSERT INTO initial_load_orders
      SELECT
        order_id,
        parseDateTime(order_ts, '%Y-%m-%dT%H:%i:%s.%fZ') as order_ts,
        customer_id,
        amount_cents,
        status,
        channel,
        country,
        promo_code,
        source_object
      FROM file('${filePath}', 'CSV', 'order_id String, order_ts String, customer_id String, amount_cents Float64, status String, channel String, country String, promo_code String, source_object String')
    `;
    executeQuery(query);
  } else {
    // CSV missing promo_code column - insert NULL
    const query = `
      INSERT INTO initial_load_orders
      SELECT
        order_id,
        parseDateTime(order_ts, '%Y-%m-%dT%H:%i:%s.%fZ') as order_ts,
        customer_id,
        amount_cents,
        status,
        channel,
        country,
        NULL as promo_code,
        source_object
      FROM file('${filePath}', 'CSV', 'order_id String, order_ts String, customer_id String, amount_cents Float64, status String, channel String, country String, source_object String')
    `;
    executeQuery(query);
  }
}

/**
 * Load a gzipped CSV file
 */
function loadCsvGzFile(filePath: string, objectKey: string): void {
  console.log(`Loading CSV.GZ file: ${filePath}`);

  // Decompress to temporary file and load
  const tempFile = `/tmp/temp_${Date.now()}.csv`;
  try {
    execSync(`gunzip -c "${filePath}" > "${tempFile}"`);
    loadCsvFile(tempFile, objectKey);
  } finally {
    // Cleanup temp file
    if (fs.existsSync(tempFile)) {
      fs.unlinkSync(tempFile);
    }
  }
}

/**
 * Load a JSONL file
 */
function loadJsonlFile(filePath: string, objectKey: string): void {
  console.log(`Loading JSONL file: ${filePath}`);

  const query = `
    INSERT INTO initial_load_orders
    SELECT
      order_id,
      parseDateTime(order_ts, '%Y-%m-%dT%H:%i:%s.%fZ') as order_ts,
      customer_id,
      amount_cents,
      status,
      channel,
      country,
      promo_code,
      source_object
    FROM file('${filePath}', 'JSONEachRow')
  `;
  executeQuery(query);
}

/**
 * Load a Parquet file
 */
function loadParquetFile(filePath: string, objectKey: string): void {
  console.log(`Loading Parquet file: ${filePath}`);

  const query = `
    INSERT INTO initial_load_orders
    SELECT
      order_id,
      parseDateTime(order_ts, '%Y-%m-%dT%H:%i:%s.%fZ') as order_ts,
      customer_id,
      amount_cents,
      status,
      channel,
      country,
      promo_code,
      source_object
    FROM file('${filePath}', 'Parquet')
  `;
  executeQuery(query);
}

/**
 * Main execution function
 */
async function main(): Promise<void> {
  console.log('=== Initial Load Process Starting ===');
  console.log(`Manifest path: ${config.S3_MANIFEST_PATH}`);

  // Parse manifest
  const manifestEntries = parseManifest(config.S3_MANIFEST_PATH);
  console.log(`Found ${manifestEntries.length} total entries in manifest`);

  // Filter for loadable entries (should_load=true, not under archive/replayed)
  const loadableEntries = manifestEntries.filter(entry =>
    entry.should_load && !entry.object_key.includes('archive/replayed')
  );
  console.log(`Found ${loadableEntries.length} entries to load`);

  // Clear existing data (if any)
  console.log('Clearing existing data from initial_load_orders table...');
  executeQuery('TRUNCATE TABLE initial_load_orders');

  let processedCount = 0;
  let totalRows = 0;

  // Process each entry
  for (const entry of loadableEntries) {
    const fullPath = path.join(BASE_PATH, entry.object_key);

    console.log(`\n--- Processing file ${++processedCount}/${loadableEntries.length} ---`);
    console.log(`Object key: ${entry.object_key}`);
    console.log(`Format: ${entry.format}`);
    console.log(`Expected rows: ${entry.row_count}`);
    console.log(`File path: ${fullPath}`);

    if (!fs.existsSync(fullPath)) {
      console.error(`File does not exist: ${fullPath}`);
      continue;
    }

    // Load based on format
    const beforeCount = parseInt(executeQuery('SELECT count(*) FROM initial_load_orders').match(/(\d+)/)?.[1] || '0', 10);

    try {
      switch (entry.format) {
        case 'csv':
          loadCsvFile(fullPath, entry.object_key);
          break;
        case 'csv.gz':
          loadCsvGzFile(fullPath, entry.object_key);
          break;
        case 'jsonl':
          loadJsonlFile(fullPath, entry.object_key);
          break;
        case 'parquet':
          loadParquetFile(fullPath, entry.object_key);
          break;
        default:
          console.error(`Unknown format: ${entry.format}`);
          continue;
      }

      const afterCount = parseInt(executeQuery('SELECT count(*) FROM initial_load_orders').match(/(\d+)/)?.[1] || '0', 10);
      const loadedRows = afterCount - beforeCount;
      totalRows = afterCount;

      console.log(`✓ Loaded ${loadedRows} rows (total: ${totalRows})`);

      if (loadedRows !== entry.row_count) {
        console.warn(`Warning: Expected ${entry.row_count} rows but loaded ${loadedRows}`);
      }
    } catch (error) {
      console.error(`Failed to load file ${entry.object_key}:`, error);
    }
  }

  console.log('\n=== Load Complete ===');
  console.log(`Total files processed: ${processedCount}`);
  console.log(`Total rows loaded: ${totalRows}`);

  // Run validation queries
  console.log('\n=== Running Validation ===');
  await runValidation();
}

/**
 * Validate the loaded data against expected metrics
 */
async function runValidation(): Promise<void> {
  const validations = [
    {
      name: 'Total unique orders',
      query: 'SELECT count(DISTINCT order_id) FROM initial_load_orders',
      expected: 600000
    },
    {
      name: 'Sum of amount_cents',
      query: 'SELECT sum(amount_cents) FROM initial_load_orders',
      expected: 904799879
    },
    {
      name: 'Status count - paid',
      query: "SELECT count(*) FROM initial_load_orders WHERE status = 'paid'",
      expected: 552070
    },
    {
      name: 'Status count - refunded',
      query: "SELECT count(*) FROM initial_load_orders WHERE status = 'refunded'",
      expected: 30032
    },
    {
      name: 'Status count - failed',
      query: "SELECT count(*) FROM initial_load_orders WHERE status = 'failed'",
      expected: 17898
    },
    {
      name: 'Distinct source_object count',
      query: 'SELECT count(DISTINCT source_object) FROM initial_load_orders',
      expected: 15
    },
    {
      name: 'Check for duplicate order_id',
      query: 'SELECT count(*) FROM (SELECT order_id, count(*) as cnt FROM initial_load_orders GROUP BY order_id HAVING cnt > 1)',
      expected: 0
    },
    {
      name: 'Check for archive/replayed rows',
      query: "SELECT count(*) FROM initial_load_orders WHERE source_object LIKE '%archive/replayed%'",
      expected: 0
    }
  ];

  let allPassed = true;

  for (const validation of validations) {
    try {
      const result = executeQuery(validation.query);
      const actualMatch = result.match(/(\d+)/);
      const actual = actualMatch ? parseInt(actualMatch[1], 10) : null;

      if (actual === validation.expected) {
        console.log(`✓ ${validation.name}: ${actual} (PASS)`);
      } else {
        console.log(`✗ ${validation.name}: Expected ${validation.expected}, got ${actual} (FAIL)`);
        allPassed = false;
      }
    } catch (error) {
      console.log(`✗ ${validation.name}: Query failed - ${error}`);
      allPassed = false;
    }
  }

  console.log(`\n=== Validation ${allPassed ? 'PASSED' : 'FAILED'} ===`);

  if (allPassed) {
    console.log('🎉 All validation checks passed! Data load successful.');
  } else {
    console.log('❌ Some validation checks failed. Please review the data.');
  }
}

// Run the script
if (require.main === module) {
  main().catch(error => {
    console.error('Script failed:', error);
    process.exit(1);
  });
}

