#!/usr/bin/env node
/**
 * Validation-only script for the loaded orders data
 */

import { execSync } from 'child_process';

/**
 * Execute ClickHouse query via moose CLI
 */
function executeQuery(query: string): string {
  try {
    console.log(`Executing query: ${query.substring(0, 50)}...`);
    const result = execSync(`moose query "${query.replace(/"/g, '\\"')}"`, { encoding: 'utf-8' });
    return result;
  } catch (error: any) {
    console.error(`Query failed: ${error.message}`);
    throw error;
  }
}

/**
 * Validate the loaded data against expected metrics
 */
async function runValidation(): Promise<void> {
  const validations = [
    {
      name: 'Total unique orders',
      query: 'SELECT count(DISTINCT order_id) as result FROM initial_load_orders',
      expected: 600000
    },
    {
      name: 'Sum of amount_cents',
      query: 'SELECT sum(amount_cents) as result FROM initial_load_orders',
      expected: 904799879
    },
    {
      name: 'Status count - paid',
      query: "SELECT count(*) as result FROM initial_load_orders WHERE status = 'paid'",
      expected: 552070
    },
    {
      name: 'Status count - refunded',
      query: "SELECT count(*) as result FROM initial_load_orders WHERE status = 'refunded'",
      expected: 30032
    },
    {
      name: 'Status count - failed',
      query: "SELECT count(*) as result FROM initial_load_orders WHERE status = 'failed'",
      expected: 17898
    },
    {
      name: 'Distinct source_object count',
      query: 'SELECT count(DISTINCT source_object) as result FROM initial_load_orders',
      expected: 15
    },
    {
      name: 'Check for duplicate order_id',
      query: 'SELECT count(*) as result FROM (SELECT order_id, count(*) as cnt FROM initial_load_orders GROUP BY order_id HAVING cnt > 1)',
      expected: 0
    },
    {
      name: 'Check for archive/replayed rows',
      query: "SELECT count(*) as result FROM initial_load_orders WHERE source_object LIKE '%archive/replayed%'",
      expected: 0
    }
  ];

  let allPassed = true;

  for (const validation of validations) {
    try {
      const result = executeQuery(validation.query);
      const actualMatch = result.match(/"result":(\d+)/);
      const actual = actualMatch ? parseInt(actualMatch[1], 10) : null;

      if (actual === validation.expected) {
        console.log(`✓ ${validation.name}: ${actual} (PASS)`);
      } else {
        console.log(`✗ ${validation.name}: Expected ${validation.expected}, got ${actual} (FAIL)`);
        allPassed = false;
      }
    } catch (error) {
      console.log(`✗ ${validation.name}: Query failed - ${error}`);
      allPassed = false;
    }
  }

  console.log(`\n=== Validation ${allPassed ? 'PASSED' : 'FAILED'} ===`);

  if (allPassed) {
    console.log('🎉 All validation checks passed! Data load successful.');
  } else {
    console.log('❌ Some validation checks failed. Please review the data.');
  }
}

// Run the validation
runValidation().catch(error => {
  console.error('Validation failed:', error);
  process.exit(1);
});
